body.usercss:

		div.i_v_outer_wrapper {
			position: absolute;
		    left: 0px;
		    top: 0px;
		    width: 100%;
		    height: 100%;
		    display: flex;
		    justify-content: center;
		    align-items: center;
		    background-color: #c2c2c2;
		}

		div.i_v_inner_wrapper {
			color: #444;
			width: 300px;
			height: 150px;
			background-color: white;
			box-shadow: 0 28px 80px -6px rgba(0, 0, 0, 0.4);
		}

		input.auth_input {
			height: 20px;
    		width: 200px;
    		padding: 10px;
		}

		div.i_v_inner_wrapper_button {
			width: 50px;
		    height: 25px;
		    padding: 5px;
		    text-align: center;
		    color: white;
		    background: #39c;
		}

		div.i_v_inner_wrapper_input_container {
			display: flex;
		    justify-content: center;
		    padding: 25px;
		}

		div.i_v_inner_wrapper_button_container {
			display: flex;
		    width: 100%;
		    justify-content: center;
		}

		div.i_v_inner_wrapper_button  {
			margin: 5px;
			cursor: pointer;
		}

userscript.function:

        	const docInfo = getContractData(Sepoa.params.CONT_NO, Sepoa.params.CONT_GL_SEQ);

			if(docInfo === false) {
				return false;
			}

			const contType = docInfo.DOC_INFO_DATA.CONT_TYPE;

			if (docInfo.DOC_INFO_DATA.STATUS != 'A') {
				if (contType === "E") {
					const signModule = '<%=CommonUtil.getConfig("sepoa.sign.module", "nx")%>'.toLowerCase();;
					if(!$share.toolkit) {
							$share.toolkit = {};
					}

					sUtils.object.extend(true, $share, docInfo);
					let target;
					switch(signModule) {
						case 'one' : {
							target = $share.toolkit.one = new SepoaCertSign({
								module: 'certModuleOne',
								methodOrder : ['samsung-pass', 'pass', 'kakao', 'naver']
							});

							$share.toolkit.one.attachEvent('onModuleReady', (secukit) => {
								doClientSign(Sepoa.params.CONT_NO, Sepoa.params.CONT_GL_SEQ, 'ONE');
							});

							$share.toolkit.one.attachEvent('onSignPass', (data) => {
								const params = sUtils.object.extend(true, {}, 
									data,
									Sepoa.params
								);

								const targetInfo = $share.SIGNER.find(e => e.SIGNER_ID == Sepoa.info.ID);
								if(targetInfo) {
									params.TARGET = targetInfo;
								}

								doSignEndEmployee(params);
							});

							break;
						}
						case 'nx' : 
						default :
							Alert('not supported module : ' + signModule);
							break;
					}

					if(target) {
						Confirm('계약서를 확인하기 위해서는 본인인증이 필요합니다.<br>본인인증을 진행하시겠습니까?', (flag) => {
							if(flag) {
								target.init();
							}
						})
					}

				} else if (contType === 'B') {
					Alert("계약서를 확인하기 위해서는 본인인증이 필요합니다.<br>본인인증을 진행하시겠습니까?", (flag) => {
						if(flag) {
							let contNo = Sepoa.request.CONT_NO;
							let contGlSeq = Sepoa.request.CONT_GL_SEQ;

							const authCellObj = {
								CONT_NO : contNo,
								CONT_GL_SEQ : contGlSeq
							};

							doRequestAuthCall(authCellObj)
						}
					})
				}
			} else {
				let docUrl;

				if (contType === "E") { // 임직원일 때
					docUrl = '/EmployeeContract/Module/EmployeeContractModuleLayout.sux';
				} else if (contType === 'B') { // 거래처일 때
					docUrl = '/Contract/Module/ContractModuleLayout.sux';
				}

				const addHidden = function(form, name, value) {
                     const input = document.createElement('input');
                     input.type = 'hidden';
                     input.name = name;
                     input.value = value;
                     form.insertBefore(input, null);
                 }

                 const form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);
                 const target = Sepoa.request;
                 if(target) {
                     target['parameterId'] = 'LINK_' + new Date().getTime();
                     target['isPopup'] = true;
                     target['onLink'] = true;
                     target['isRealPopup'] = true;
                 }

                 for(let entry of Object.entries(target)) {
                     const [key, value] = entry;
                     addHidden(form, key, value);
                 }

                 if(!SUX.root.modalPopupInfo){
                     SUX.root.modalPopupInfo = {};
                 }
                 SUX.root.modalPopupInfo[target['parameterId']] = {
                     params: target
                 };

                 form.target = window.name;
                 form.action = window.CONTEXT_NAME + docUrl;
                 form.method = 'post';
                 form.submit();
			}


           	$docNumber = sUtils.string.randomUUID();
        	if($authContainer) {
        		$authContainer.remove();
        	}

        	data["DOC_NUMBER"] = $docNumber;

        	let outerWrapper = $authContainer = document.createElement("div");
        	outerWrapper.className = "i_v_outer_wrapper";

        	let innerWrapper = document.createElement("div");
        	innerWrapper.className = "i_v_inner_wrapper";

        	let inputContainer = document.createElement("div");
        	inputContainer.className = "i_v_inner_wrapper_input_container";

        	let authInput = document.createElement("input");
        	authInput.className = "auth_input"
        	authInput.id = "auth_input_value"
        	authInput.type = "input"
        	authInput.placeholder = "-를 제외한 사업자번호를 입력해주세요";

        	let buttonContainer = document.createElement("div");
        	buttonContainer.className = "i_v_inner_wrapper_button_container"

        	let confirmButton = document.createElement("div");
        	confirmButton.className = "i_v_inner_wrapper_button i_v_inner_wrapper_button_confirm";
        	confirmButton.onclick = function(e) {
        		let authInputValue = container.getElementsByClassName("auth_input")[0].value
        		doRequestCheckAuth(authInputValue); 
        	}

        	confirmButton.innerHTML = "확인";

        	inputContainer.appendChild(authInput);
        	buttonContainer.appendChild(confirmButton);

        	innerWrapper.appendChild(inputContainer);
			innerWrapper.appendChild(buttonContainer);

			outerWrapper.appendChild(innerWrapper);
			container.appendChild(outerWrapper);


if(sUtils.string.isBlank(contNo,) && sUtils.string.isBlank(contGlSeq)) {
    return false;
}

const config = {
    url : window.CONTEXT_NAME+'/SepoaActionController.sux',
    async : false,
    contentType : 'json'
};

const params = {
    module : 'contract',
    action : 'doDocumentDetail',
    CONNECTION : 'CONNECTION',
    CONT_NO: contNo,
    CONT_GL_SEQ: contGlSeq
};

const so = sUtils.multipart.send(config, params);
if(so.flag === false) {
    Alert(so.message);
    return false;
}

return so.result[0];


const config = {
    url : window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback : function(res, config, params) {
            if(res.status == 1){
                $share.toolkit[config._SIGN_TYPE.toLowerCase()].doSign({
                    SIGN_ORG_VALUE : res.result[0].SIGN_HASH,
                    SIGN_KEY : res.result[0].SIGN_KEY
                });
            } else {
                Alert(res.message);
            }
        }
    },
    _SIGN_TYPE : signModule
}

const params = {
    module : 'contract',
    action : 'doSelectClientSignInfo',
    CONNECTION : 'CONNECTION',
    CONT_NO : contNo,
    CONT_GL_SEQ : contGlSeq,
    CHECK_CURRENT_SIGNER : false
}

sUtils.multipart.send(config, params);


        	const checkObj = {
        		AUTH_NUMBER: authNumber,
        		DOC_NUMBER: $docNumber,
        		CONT_NO: Sepoa.request.CONT_NO,
        		CONT_GL_SEQ: Sepoa.request.CONT_GL_SEQ
        	}

   			doServiceAjax('sepoa.svc.otp.SepoaContractOtpService', 'CONNECTION', 'checkAuthNumber' , checkObj, function(so) {
				let status = so.status;
				switch(status) {
					case "1":
							const addHidden = function(form, name, value) {
                                const input = document.createElement('input');
                                input.type = 'hidden';
                                input.name = name;
                                input.value = value;
                                form.insertBefore(input, null);
                            }

                            const form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);

                            const target = Sepoa.request;
                            if(target) {
                                target['parameterId'] = 'LINK_' + new Date().getTime();
                                target['isPopup'] = true;
                                target['onLink'] = true;
                                target['isRealPopup'] = true;
                            }

                            for(let entry of Object.entries(target)) {
                                const [key, value] = entry;
                                addHidden(form, key, value);
                            }

                            if(!SUX.root.modalPopupInfo){
                                SUX.root.modalPopupInfo = {};
                            }
                            SUX.root.modalPopupInfo[target['parameterId']] = {
                                params: target
                            };

                            form.target = window.name;
                            form.action = window.CONTEXT_NAME + '/Contract/Module/ContractModuleLayout.sux';
                            form.method = 'post';
                            form.submit();
						break;
					case "2":
						Alert(Sepoa.cache.text.get("POA_CONTRACT.CHECK_IRS_NO_FORMAT")); // -를 제외한 11자리 번호를 입력해주세요
						document.getElementById("auth_input_value").value = '';
						break;
					case "3":
						Alert(Sepoa.cache.text.get("POA_CONTRACT.SIGNNER_NOT_EXIST")); // 해당 번호의 서명자 데이터가 존재하지 않습니다.
						document.getElementById("auth_input_value").value = '';
						break;
					case "4":
						Alert(Sepoa.cache.text.get("POA_CONTRACT.OTP_DATA_NOT_FOUND")); // 인증정보를 찾을 수 없습니다.
						document.getElementById("auth_input_value").value = '';
						break;
					default:
						Alert(Sepoa.cache.text.get("MESSAGE.1002")); // 처리 중 오류가 발생하였습니다.
						break;
				}
			}, false);


const config = {
    url : window.CONTEXT_NAME + '/SepoaSignOne.sux?type=verify',
    contentType : 'json',
    on : {
        callback : (res) => {
            if(res.flag) {
                const addHidden = function(form, name, value) {
                    const input = document.createElement('input');
                    input.type = 'hidden';
                    input.name = name;
                    input.value = value;
                    form.insertBefore(input, null);
                }

                const form = document.body.appendChild($('<form target="sepoa-link-frame" style="display:none"></form>')[0]);

                const target = res;
                if(target) {
                    target['parameterId'] = 'LINK_' + new Date().getTime();
                    target['isPopup'] = true;
                    target['onLink'] = true;
                    target['isRealPopup'] = true;
                }

                for(let entry of Object.entries(target)) {
                    const [key, value] = entry;
                    addHidden(form, key, value);
                }

                if(!SUX.root.modalPopupInfo){
                    SUX.root.modalPopupInfo = {};
                }
                SUX.root.modalPopupInfo[target['parameterId']] = {
                    params: target
                };

                form.target = window.name;
                form.action = window.CONTEXT_NAME + '/EmployeeContract/Module/EmployeeContractModuleLayout.sux';
                form.method = 'post';
                form.submit();
            } else {
                Alert(res.message);
            }
        }
    }
};

const params = sUtils.object.extend(true, {}, data);

sUtils.multipart.send(config, params);
